"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { 
  LayoutDashboard, 
  ShoppingBag, 
  ShoppingCart, 
  Users, 
  Settings,
  LogOut,
  Store,
  Menu,
  X
} from "lucide-react";

const routes = [
  {
    label: "Dashboard",
    icon: LayoutDashboard,
    href: "/admin/dashboard",
  },
  {
    label: "Products",
    icon: ShoppingBag,
    href: "/admin/products",
  },
  {
    label: "Orders",
    icon: ShoppingCart,
    href: "/admin/orders",
  },
  {
    label: "Customers",
    icon: Users,
    href: "/admin/customers",
  },
  {
    label: "Settings",
    icon: Settings,
    href: "/admin/settings",
  },
];

export function AdminSidebar() {
  const pathname = usePathname();

  return (
    <div className="hidden lg:flex w-64 flex-col fixed inset-y-0 z-50 bg-white border-r border-gray-200 text-gray-500">
      <div className="p-6 flex items-center gap-x-3 mb-4">
        <div className="w-10 h-10 rounded-xl bg-linear-to-br from-green-500 to-green-700 flex items-center justify-center shadow-lg shadow-green-500/30">
          <Store className="w-6 h-6 text-white" />
        </div>
        <h1 className="text-xl font-bold tracking-tight">MeatStore Admin</h1>
      </div>

      <div className="flex-1 px-4 py-2 space-y-2">
        {routes.map((route) => {
          const isActive = pathname === route.href || pathname.startsWith(`${route.href}/`);
          
          return (
            <Link
              key={route.href}
              href={route.href}
              className={`group flex items-center px-4 py-3 text-sm font-medium rounded-xl transition-all duration-200 ease-in-out ${
                isActive 
                  ? "bg-gray-100 text-green-600" 
                  : "text-zinc-400 hover:text-black/20 hover:bg-gray-100"
              }`}
            >
              <div className="flex items-center flex-1">
                <route.icon className={`w-5 h-5 mr-3 transition-colors ${isActive ? "text-green-600" : "group-hover:text-green-600"}`} />
                {route.label}
              </div>
            </Link>
          )
        })}
      </div>

      <div className="p-4 mt-auto">
        <button className="flex items-center w-full px-4 py-3 text-sm font-medium text-red-400 rounded-xl hover:bg-red-500/10 transition-colors">
          <LogOut className="w-5 h-5 mr-3" />
          Logout
        </button>
      </div>
    </div>
  );
}

export function MobileSidebar() {
  const pathname = usePathname();
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="lg:hidden">
      <button 
        onClick={() => setIsOpen(true)}
        className="p-2 -ml-2 hover:bg-black/5 rounded-lg transition-colors"
      >
        <Menu className="w-6 h-6 text-zinc-900" />
      </button>

      {/* Backdrop */}
      {isOpen && (
        <div 
          className="fixed inset-0 z-60 bg-black/60 backdrop-blur-sm transition-opacity"
          onClick={() => setIsOpen(false)}
        />
      )}
      
      {/* Sidebar Dropdown/Slide */}
      <div 
        className={`fixed inset-y-0 left-0 z-70 w-72 bg-[#0A0A0A] text-white shadow-2xl transform transition-transform duration-300 ease-in-out ${
          isOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="p-6 flex items-center justify-between mb-4">
          <div className="flex items-center gap-x-3">
            <div className="w-10 h-10 rounded-xl bg-linear-to-br from-green-500 to-green-700 flex items-center justify-center shadow-lg shadow-green-500/30">
              <Store className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">MeatStore</h1>
          </div>
          <button 
            onClick={() => setIsOpen(false)}
            className="p-2 text-zinc-400 hover:text-white transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 px-4 py-2 space-y-2">
          {routes.map((route) => {
            const isActive = pathname === route.href || pathname.startsWith(`${route.href}/`);
            
            return (
              <Link
                key={route.href}
                href={route.href}
                onClick={() => setIsOpen(false)}
                className={`group flex items-center px-4 py-3 text-sm font-medium rounded-xl transition-all duration-200 ease-in-out ${
                  isActive 
                    ? "bg-white/10 text-green-400" 
                    : "text-zinc-400 hover:text-white hover:bg-white/5"
                }`}
              >
                <div className="flex items-center flex-1">
                  <route.icon className={`w-5 h-5 mr-3 transition-colors ${isActive ? "text-green-400" : "group-hover:text-green-400"}`} />
                  {route.label}
                </div>
              </Link>
            )
          })}
        </div>

        <div className="absolute bottom-6 left-4 right-4">
          <button className="flex justify-center items-center w-full px-4 py-3 text-sm font-medium text-red-400 rounded-xl hover:bg-red-500/10 transition-colors border border-red-500/20">
            <LogOut className="w-5 h-5 mr-3" />
            Logout
          </button>
        </div>
      </div>
    </div>
  );
}
